&lt;p data-start=&quot;1220&quot; data-end=&quot;1237&quot;&gt;&lt;span style=&quot;color: rgb(30, 17, 80);&quot;&gt;&lt;strong data-start=&quot;1220&quot; data-end=&quot;1237&quot;&gt;What We Offer&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul data-start=&quot;1239&quot; data-end=&quot;1508&quot;&gt;
&lt;li style=&quot;color: rgb(30, 17, 80);&quot; data-start=&quot;1239&quot; data-end=&quot;1310&quot;&gt;
&lt;p data-start=&quot;1241&quot; data-end=&quot;1310&quot;&gt;&lt;span style=&quot;color: rgb(30, 17, 80);&quot;&gt;Competitive base salary with monthly commissions or bonus potential&lt;/span&gt;&lt;/p&gt;
